"""Render audited validation-selected equal-update allocation results."""
import csv,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
OUT=Path('results/thrml_spw/sample_allocation')
def rows(name):
    with (OUT/name).open() as f:return list(csv.DictReader(f))
def main():
    assert json.loads((OUT/'evidence_audit.json').read_text())['passed'];p=json.loads((OUT/'protocol.json').read_text());a=json.loads((OUT/'allocation.json').read_text());summary=rows('test_summary.csv');base=rows('test_baseline_metrics.csv');pair=json.loads((OUT/'paired_summary.json').read_text());cost=json.loads((OUT/'resource_ledger.json').read_text());sens=rows('validation_sensitivities.csv');stable=json.loads((OUT/'selection_stability.json').read_text());u=next(r for r in summary if r['condition']=='uniform');c=next(r for r in summary if r['condition']=='allocated');fp=next(r for r in base if r['condition']=='FP32');interpretation='includes zero' if pair['CE_sensitivity_low']<=0<=pair['CE_sensitivity_high'] else ('is below zero' if pair['CE_sensitivity_high']<0 else 'is above zero')
    fig,ax=plt.subplots(2,2,figsize=(12,8),layout='constrained');x=np.arange(24);ax[0,0].bar(x,a['samples']);ax[0,0].axhline(1024,ls='--',color='black',label='Uniform');ax[0,0].set(xlabel='Projection in forward order',ylabel='Samples',title='Frozen validation-only schedule');ax[0,0].legend(fontsize=8)
    ax[0,1].plot([0,1],[100*(float(r['relative_perplexity'])-1) for r in [u,c]],'o',label='Point');ax[0,1].plot([0,1],[100*(float(r['bootstrap_relative_upper'])-1) for r in [u,c]],'_',ms=14,label='Crossed upper sensitivity bound');ax[0,1].axhline(5,ls='--',color='black',label='Frozen 5% rule');ax[0,1].set(xticks=[0,1],xticklabels=['Uniform','Allocated'],ylabel='PPL increase over fresh FP32 (%)',title='Same weighted observed updates');ax[0,1].legend(fontsize=7)
    y=pair['CE_difference'];ax[1,0].errorbar([0],[y],yerr=[[y-pair['CE_sensitivity_low']],[pair['CE_sensitivity_high']-y]],fmt='o',capsize=5);ax[1,0].axhline(0,ls='--',color='black');ax[1,0].set(xticks=[0],xticklabels=['Allocated minus uniform'],ylabel='CE difference (nats/target)',title='Paired crossed seed/bank sensitivity')
    v=np.array([[1,1],[sum(a['samples'])/24576,1],[max(a['samples'])/1024,1]]);xx=np.arange(3);ax[1,1].bar(xx-.16,v[:,1],width=.32,label='Uniform');ax[1,1].bar(xx+.16,v[:,0],width=.32,label='Allocated');ax[1,1].set(xticks=xx,xticklabels=['Weighted updates','Sum layer samples','Max layer samples'],ylabel='Ratio to uniform',title='Counters are not physical energy/latency');ax[1,1].legend(fontsize=8)
    for axis in ax.ravel():axis.grid(axis='y',alpha=.2)
    fig.savefig('results/thrml_spw/sample_allocation_evidence.png',dpi=180);plt.close(fig)
    parts=['# Validation-selected sampling at equal observed-update budget\n']
    parts.append(f'At exactly matched weighted sampling updates, the frozen allocation gives perplexity **{float(c["perplexity"]):.3f}** versus **{float(u["perplexity"]):.3f}** for uniform T1024; fresh FP32 is **{float(fp["perplexity"]):.3f}**. The paired CE sensitivity interval {interpretation}. Allocated point quality gate: **{c["point_passed"]}**; strict gate: **{c["passes"]}**. The validation surrogate optimum is not treated as proof of neural improvement. The broad goal remains active.\n')
    parts.append('## Prospective selection and fresh test\n')
    parts.append('The protocol fixes all choices before validation/native sampling or new test scoring. It uses the same pinned DistilGPT-2 checkpoint, all six blocks\' 24 affine projections (42,467,328 normalized signed weights; 51.84% of unique parameters), eight-bit [-4,4] fields and group128 ranges. Embeddings/head, LayerNorm and biases stay deterministic. Devices are ideal independent unary THRML p-bits; every converted weight remains a free node. This is broader matrix conversion, not full-model or physical hardware proof. Official THRML0.1.4 is pinned at commit2d54cd8404df85bb65703d7e8b4e84e48c1b72a9.\n')
    parts.append('Thirty-two unused validation windows and32 separately unused test windows (65 tokens each;2,048 targets per split) are reserved from the correct WikiText-2 validation/test parquet streams. Every recorded offset vector is catalogued with its split; all old token rows and new exclusions are independently verified. Numeric offsets from different splits are not treated as the same text. The consumed earlier test results are outside the allocation rule.\n')
    parts.append('On validation only, one projection at a time uses nativeT256 while the other23 converted matrices use their analytic programmed means castF32. Five sampling seeds per projection give120 isolated-layer model cases. Define S_l=max(meanCE_isolated_l-CE_mean_model,1e-4). The fixed surrogate minimizes sum_l S_l/(T_l/256), with T_l in{256,512,1024,2048,4096}, under exact sum_l(N_l/589824)*(T_l/256)=288. Dynamic programming resolves exact cost ties lexicographically. An independent SciPy/HiGHS binary mixed-integer solve with zero optimality gap verifies the global surrogate optimum. Labels/scores come solely from validation; no hyperparameter search or rescue follows test results. The inverseT/separable loss model may miss layer interactions and noisy sensitivity estimates.\n')
    predicted=100*(1-a['objective']/a['uniform_surrogate_objective']);parts.append(f'The selected surrogate is {a["objective"]:.8f} versus {a["uniform_surrogate_objective"]:.8f} for uniform sampling ({predicted:.2f}% lower predicted excess loss). This number is a validation-model prediction, not a measured held-out quality gain. The schedule is frozen and independently audited before any test baseline or stochastic test model is evaluated.\n')
    parts.append('Both conditions then execute all24 native projections on actual current stochastic inputs in five fresh test seeds. Identical root/fold keys pair conditions; different T changes internal PRNG splitting, so differing budgets do not share a full sample prefix. Native output accumulation precedes original nonlinearities. All ten full test cases and all25 prefixes per seed are retained, with no winner selected from test.\n')
    parts.append('## Held-out task results\n\n| Condition | Perplexity | Token accuracy (%) |\n|---|---:|---:|')
    for r in base:parts.append(f'| {r["condition"]} | {float(r["perplexity"]):.3f} | {100*float(r["token_accuracy"]):.3f} |')
    for r in [u,c]:parts.append(f'| {r["condition"]} | {float(r["perplexity"]):.3f} | {100*float(r["token_accuracy"]):.3f} |')
    parts.append('\n| Native condition | PPL increase (%) | Crossed upper bound (%) | Accuracy delta (pp) | Point gate | Strict gate |\n|---|---:|---:|---:|---|---|')
    for r in [u,c]:parts.append(f'| {r["condition"]} | {100*(float(r["relative_perplexity"])-1):.3f} | {100*(float(r["bootstrap_relative_upper"])-1):.3f} | {100*float(r["accuracy_difference"]):+.4f} | {r["point_passed"]} | {r["passes"]} |')
    parts.append(f'\nAllocated-minus-uniform CE difference is {pair["CE_difference"]:+.6f} nats/target, with crossed sensitivity interval [{pair["CE_sensitivity_low"]:+.6f}, {pair["CE_sensitivity_high"]:+.6f}]. PPL ratio is {pair["perplexity_ratio"]:.6f}; accuracy difference is {100*pair["accuracy_difference"]:+.4f} percentage points, with interval [{100*pair["accuracy_sensitivity_low"]:+.4f}, {100*pair["accuracy_sensitivity_high"]:+.4f}]. Resampling crosses five sampling seeds with four whole eight-context banks,10,000 times at fixed seed2026117002. These are descriptive sensitivity intervals under exchangeable clusters, not guaranteed coverage/equivalence. One checkpoint and short contexts limit generalization.\n')
    parts.append('The unchanged point rule requires PPL/FP32≤1.05 and accuracy loss≤1 percentage point. The strict rule also requires crossed97.5% CE upper bound≤log1.05 and accuracy2.5% lower bound≥−0.01. All previous quality failures remain unchanged.\n')
    parts.append('## Schedule, stability and cost\n\n| Projection | Validation CE delta | Floored coefficient | Selected samples |\n|---|---:|---:|---:|')
    for r in sens:parts.append(f'| {r["stage"]}: {r["module"]} | {float(r["raw_CE_delta"]):+.6f} | {float(r["floored_coefficient"]):.6f} | {r["selected_samples"]} |')
    changes=[v['layers_different_from_frozen'] for v in stable['rows']];parts.append(f'\nA separate post-hoc validation-only leave-one-seed/bank diagnostic changes {min(changes)}–{max(changes)} layer budgets relative to the frozen schedule. These alternative schedules were never scored on test or selected, and the allocation hash stayed unchanged. This describes sensitivity to the small validation cohort rather than uncertainty coverage.\n')
    parts.append(f'Each method uses exactly {cost["test_updates_per_condition_per_seed"]:,} observed node updates per test seed and the same42,467,328 free nodes. Weighted mean samples remains1024. Sum layer samples changes24576→{sum(a["samples"])}; max layer budget changes1024→{max(a["samples"])}. Serialized sampling-round count and maximum layer budget are different counters; neither establishes physical chip latency. Device/control/readout/accumulation energy is unmeasured.\n')
    parts.append(f'Validation selection costs {cost["validation_selection_observed_updates"]:,} native observed updates separately. Test production costs {cost["test_production_observed_updates"]:,}. Independent output-sum and frequency checks each replay native states, and the original failed combined-observer attempt is retained. Total executed native observed updates for this step, including selection, test, failed check and verification, is {cost["total_executed_native_observed_updates"]:,}. These are redraw counters, not necessarily bit flips or thermal transitions.\n')
    parts.append(f'Control/range/bias payload stays {cost["control_range_bias_payload_bytes"]:,} bytes (8.53125bits/converted weight), plus48 schedule bytes rather than a2byte uniform counter. One free node is not one total stored bit. Packed test output storage is {cost["lossless_packed_test_output_bytes"]:,} bytes for {cost["same_arrays_unpacked_float32_bytes"]:,} bytes of F32 values. Byte-plane packing preserves every float bit, validated on special/random patterns and representative data, and in every exact native/model replay. This is software evidence storage, not model compression or hardware advantage.\n')
    parts.append('## Independent evidence and retained numerical check\n')
    parts.append('Independent original-model hooks reconstruct validation means, both validation baselines, all120 isolated cases, all240 test inputs and every final test loss/prediction. Every native output is independently reproduced byte for byte by public THRML factors with dynamic fields/defaultF32; separate integer-frequency observers check a float64 linear identity and a predeclared IEEE forward-error envelope. The2e-5 discrepancy flag is recorded descriptively, with failures retained rather than adjusted after outcomes. All250 test-prefix metric rows, both quality decisions, all60,000 bootstrap values, schedule constraints and budgets are independently recomputed. Source/data/control hashes and raw outputs/token metrics remain preserved; regenerable inputs carry exact original NPY hashes.\n')
    parts.append('The first combined count-plus-sum observer passed ten cases but failed bitwise agreement on the larger MLP projection. Its source/logs and eleven executed replay operators are preserved. Separating output-sum replay from the frequency observer restored the required exact production output without changing the acceptance rule or any model result. The observer/compilation context affected F32 results; a particular compiler optimization is not isolated as the cause. This failed attempt supplies no extra quality evidence.\n')
    parts.append('The broad goal remains active for better validated precision/range/training tradeoffs, nonideal/correlated/clocked broader conversion, embedding/head coverage, longer contexts and additional models, relevant application comparisons and measured physical costs. Surrogate optimality or one bounded task result cannot establish systems superiority.\n')
    parts.append('## Reproduction\n\n```bash\nOPENBLAS_NUM_THREADS=4 .venv/bin/python -m research.thrml_spw.sample_allocation_validation\nOPENBLAS_NUM_THREADS=4 .venv/bin/python -m research.thrml_spw.audit_sample_allocation_validation\nOPENBLAS_NUM_THREADS=4 .venv-thrml/bin/python -m research.thrml_spw.verify_sample_allocation_selection\nOPENBLAS_NUM_THREADS=4 .venv/bin/python -m research.thrml_spw.sample_allocation_test\nOPENBLAS_NUM_THREADS=4 .venv/bin/python -m research.thrml_spw.audit_sample_allocation_test_paths\nOPENBLAS_NUM_THREADS=4 .venv/bin/python -m research.thrml_spw.verify_sample_allocation_test\n.venv/bin/python -m research.thrml_spw.sample_allocation_resources\n.venv-thrml/bin/python -m research.thrml_spw.sample_allocation_report\n```\nCompleted validation/test drivers verify caches without new sampling; independent audits intentionally replay preserved keys. The immutable allocation is already present, so its one-time selector refuses to overwrite it.\n')
    text='\n'.join(parts)+'\n'
    for old,new in {'THRML0.1.4':'THRML 0.1.4','commit2d':'commit 2d','and32':'and 32','each;2,048':'each; 2,048','nativeT256':'native T256','other23':'other 23','castF32':'cast F32','give120':'give 120','all24':'all 24','all25':'all 25','banks,10,000':'banks, 10,000','seed2026117002':'seed 2026117002','crossed97.5%':'crossed 97.5%','accuracy2.5%':'accuracy 2.5%','same42,467,328':'same 42,467,328','remains1024':'remains 1024','changes24576':'changes 24576','changes1024':'changes 1024','8.53125bits':'8.53125 bits','plus48':'plus 48','a2byte':'a 2-byte','all120':'all 120','all240':'all 240','all250':'all 250','all60,000':'all 60,000','The2e-5':'The 2e-5'}.items():text=text.replace(old,new)
    Path('results/thrml_spw/SAMPLE_ALLOCATION_REPORT.md').write_text(text);print(json.dumps({'summary':summary,'paired':pair,'total_native_updates':cost['total_executed_native_observed_updates'],'goal_status':'active'},indent=2))
if __name__=='__main__':main()
